queries.sparql:
SELECT ?label ?title ?issued (GROUP_CONCAT(?type; separator=" / ") AS ?types) ?entry
WHERE {
  ?entry a bibo:Document ;
         sqp:citationLabel ?label ;
         dct:title ?title ;
         dct:issued ?issued ;
         prism:volume ?volume ;
         prism:number ?issue ;
         sqp:entryNumber ?n .
  OPTIONAL { ?entry dct:type/skos:notation ?type }
  # Sort keys as plain integers: volume and issue are strings in PRISM.
  BIND(xsd:integer(?volume) AS ?v)
  BIND(xsd:integer(?issue) AS ?i)
  BIND(xsd:integer(?n) AS ?e)
}
GROUP BY ?label ?title ?issued ?entry ?v ?i ?e
ORDER BY ?v ?i ?e

SELECT ?type ?label ?coar (COUNT(DISTINCT ?entry) AS ?entries)
WHERE {
  ?entry a bibo:Document ;
         dct:type ?concept .
  ?concept skos:notation ?type ;
           skos:prefLabel ?label .
  FILTER(LANG(?label) = "en")
  OPTIONAL { ?concept skos:exactMatch|skos:closeMatch ?coar }
}
GROUP BY ?type ?label ?coar
ORDER BY DESC(?entries) ?type

SELECT ?year (COUNT(DISTINCT ?entry) AS ?entries)
WHERE {
  ?entry a bibo:Document ;
         dct:issued ?issued .
  BIND(SUBSTR(STR(?issued), 1, 4) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?year)

SELECT ?volume ?issue ?sigil (COUNT(?entry) AS ?entries) ?issueIri
WHERE {
  ?entry a bibo:Document ;
         dcat:inSeries ?issueIri .
  ?issueIri prism:number ?issue ;
            sqp:sigil ?sigil ;
            dcat:inSeries ?volumeIri .
  ?volumeIri prism:volume ?volume .
}
GROUP BY ?volume ?issue ?sigil ?issueIri
ORDER BY DESC(xsd:integer(?volume)) xsd:integer(?issue)

SELECT ?name (COUNT(DISTINCT ?entry) AS ?entries) ?orcid ?person
WHERE {
  ?entry a bibo:Document ;
         dct:creator|dct:contributor|bibo:editor ?person .
  ?person foaf:name ?name .
  OPTIONAL { ?person owl:sameAs ?orcid }
}
GROUP BY ?person ?name ?orcid
ORDER BY DESC(?entries) ?name

SELECT ?language (COUNT(DISTINCT ?entry) AS ?entries) (SUM(?guess) AS ?guessed)
WHERE {
  ?entry a bibo:Document ;
         dct:language ?authority .
  BIND(IF(?authority = <http://publications.europa.eu/resource/authority/language/DEU>, "de",
       IF(?authority = <http://publications.europa.eu/resource/authority/language/ENG>, "en",
          STR(?authority))) AS ?language)
  OPTIONAL { ?entry sqp:languageGuessed ?g }
  BIND(IF(COALESCE(?g, false), 1, 0) AS ?guess)
}
GROUP BY ?language
ORDER BY DESC(?entries)

SELECT ?event ?start ?place ?wkt (COUNT(DISTINCT ?entry) AS ?entries)
WHERE {
  ?entry bibo:presentedAt ?e .
  ?e rdfs:label ?event ;
     schema:location ?p .
  OPTIONAL { ?e schema:startDate ?start }
  ?p rdfs:label ?place ;
     geo:hasGeometry/geo:asWKT ?wkt .
}
GROUP BY ?event ?start ?place ?wkt
ORDER BY DESC(?start) ?event

SELECT ?title ?person ?begin ?entry
WHERE {
  ?creation a crm:E65_Creation ;
            crm:P94_has_created ?entry ;
            crm:P14_carried_out_by ?actor ;
            crm:P4_has_time-span/crm:P82a_begin_of_the_begin ?begin .
  ?entry crm:P102_has_title/crm:P190_has_symbolic_content ?title .
  ?actor rdfs:label ?person .
}
ORDER BY DESC(?begin) ?title ?person
LIMIT 200

SELECT ?event ?place ?wkt ?title ?pdf
WHERE {
  ?activity a crm:E7_Activity ;
            crm:P1_is_identified_by/crm:P190_has_symbolic_content ?event ;
            crm:P16_used_specific_object ?entry ;
            crm:P7_took_place_at ?p .
  ?p crm:P168_place_is_defined_by ?wkt ;
     rdfs:label ?place .
  ?entry crm:P102_has_title/crm:P190_has_symbolic_content ?title .
  OPTIONAL { ?pdf crm:P165_incorporates ?entry ; a crmdig:D1_Digital_Object }
}
ORDER BY ?event ?title

SELECT ?volume (COUNT(?file) AS ?files) (ROUND(SUM(?bytes) / 10485.76) / 100 AS ?MiB)
WHERE {
  ?entry a bibo:Document ;
         prism:volume ?volume ;
         dcat:distribution ?file .
  ?file dcat:byteSize ?bytes .
}
GROUP BY ?volume
ORDER BY DESC(xsd:integer(?volume))
